16	)
17	
18	// This file verifies online configuration switches through the admin API
19	// (POST /load) against a real `caddy` subprocess:
20	//
21	//   - a successful load starts serving the new configuration as soon as the
22	//     admin response reports success, while requests that were already in
23	//     flight keep being served by the configuration that accepted them;
24	//   - a configuration that fails to parse/provision/start is rejected and the
25	//     previously running configuration keeps serving without any gap in which
26	//     the listen address is unconfigured;
27	//   - success, failure and success again stay isolated: each round's requests
28	//     and responses match exactly the configuration of that round.
29	//
30	// The matrix runs twice: on a plaintext HTTP/1.1 listener (native JSON
31	// submitted to /load) and on an HTTPS listener configured with the Caddyfile
32	// `tls internal` (Caddyfile submitted to /load, negotiated over HTTP/2). The
33	// protocol must not change any switch boundary, rollback or in-flight
34	// semantics.
35	
36	const (
37		// holdPrefix/holdSuffix are the two halves of the response body that the
38		// test upstream sends for /hold. The prefix is flushed before the config
39		// switch; the suffix is only flushed when the test releases the upstream
40		// connection, so the client can prove the in-flight response is neither
41		// spliced with the new configuration, truncated nor duplicated.
42		holdPrefix = "A-inflight-prefix----"
43		holdSuffix = "A-inflight-suffix----"
44	
45		versionABody = "variant-a-payload"
46		versionBBody = "variant-b-payload"
47	)
48	
49	// reloadHoldUpstream is a test-process HTTP/1.1 upstream that /hold is proxied
50	// to. For each /hold request it writes the A status line, an A marker header
51	// and the A body prefix, then parks the (hijacked) connection until the test
52	// releases it, at which point it writes the suffix and the terminating chunk
53	// and closes the connection.
54	type reloadHoldUpstream struct {
55		ln          net.Listener
56		mu          sync.Mutex
57		held        []net.Conn
58		variantHits map[string]int
59	}
60	
61	func newReloadHoldUpstream(t *testing.T) *reloadHoldUpstream {
62		t.Helper()
63		ln, err := net.Listen("tcp", "127.0.0.1:0")
64		if err != nil {
65			t.Fatalf("listen for hold upstream: %v", err)
66		}
67		u := &reloadHoldUpstream{
68			ln:          ln,
69			variantHits: make(map[string]int),
70		}
71		srv := &http.Server{Handler: http.HandlerFunc(u.handle)}
72		go srv.Serve(ln)
73		t.Cleanup(func() { srv.Close(); ln.Close() })
74		return u
75	}
76	
77	func (u *reloadHoldUpstream) addr() string { return u.ln.Addr().String() }
78	
79	func (u *reloadHoldUpstream) variantHit(variant string) int {
80		u.mu.Lock()
81		defer u.mu.Unlock()
82		return u.variantHits[variant]
83	}
84	
85	// releaseAll finalizes every held response with the A suffix and then closes
86	// its connection. It is the only way a held response may complete.
87	func (u *reloadHoldUpstream) releaseAll() {
88		u.mu.Lock()
89		conns := u.held
90		u.held = nil
91		u.mu.Unlock()
92		for _, conn := range conns {
93			fmt.Fprintf(conn, "%x\r\n%s\r\n", len(holdSuffix), holdSuffix)
94			_, _ = io.WriteString(conn, "0\r\n\r\n")
95			_ = conn.Close()
96		}
97	}
98	
99	func (u *reloadHoldUpstream) handle(w http.ResponseWriter, r *http.Request) {
100		variant := r.Header.Get("X-Variant")
101		u.mu.Lock()
102		u.variantHits[variant]++
103		u.mu.Unlock()
104	
105		conn, rw, err := w.(http.Hijacker).Hijack()
106		if err != nil {
107			panic(err)
108		}
109		_, _ = io.WriteString(rw,
110			"HTTP/1.1 200 OK\r\n"+
111				"X-Hold-Marker: hold-A\r\n"+
112				"Transfer-Encoding: chunked\r\n"+
113				"\r\n")
114		fmt.Fprintf(rw, "%x\r\n%s\r\n", len(holdPrefix), holdPrefix)
115		_ = rw.Flush()
116	
117		u.mu.Lock()
118		u.held = append(u.held, conn)
119		u.mu.Unlock()
120	
121		// park the handler until Caddy (or releaseAll) closes the connection;
122		// after a Hijack the stdlib server no longer touches this connection
123		_, _ = io.Copy(io.Discard, rw)
124	}
125	
126	// inflightHold is one /hold request running in its own goroutine while the
127	// test drives configuration switches on other connections.
128	type inflightHold struct {
129		prefixReady chan struct{}
130		done        chan struct{}
131	
132		resp      *http.Response
133		prefix    []byte
134		prefixErr error
135		rest      []byte
136		restErr   error
137	}
138	
139	func startInflightHold(t *testing.T, client *http.Client, baseURL string) *inflightHold {
140		t.Helper()
141		h := &inflightHold{
142			prefixReady: make(chan struct{}),
143			done:        make(chan struct{}),
144		}
145		go func() {
146			defer close(h.done)
147			resp, err := client.Get(baseURL + "/hold")
148			if err != nil {
149				h.prefixErr = err
150				close(h.prefixReady)
151				return
152			}
153			h.resp = resp
154			h.prefix = make([]byte, len(holdPrefix))
155			_, h.prefixErr = io.ReadFull(resp.Body, h.prefix)
156			close(h.prefixReady)
157			if h.prefixErr != nil {
158				return
159			}
160			h.rest, h.restErr = io.ReadAll(resp.Body)
161		}()
162		return h
163	}
164	
165	// waitPrefix waits until the A status line, marker header and prefix body have
166	// arrived; the configuration switch must only be started after this.
167	func (h *inflightHold) waitPrefix(t *testing.T) {
168		t.Helper()
169		select {
170		case <-h.prefixReady:
171		case <-time.After(30 * time.Second):
172			t.Fatal("held request never produced its A prefix")
173		}
174		if h.prefixErr != nil {
175			t.Fatalf("reading held prefix: %v", h.prefixErr)
176		}
177		if string(h.prefix) != holdPrefix {
178			t.Fatalf("held prefix: got %q, want %q", h.prefix, holdPrefix)
179		}
180		if h.resp.StatusCode != http.StatusOK {
181			t.Fatalf("held status: got %d, want 200", h.resp.StatusCode)
182		}
183		if got := h.resp.Header.Get("X-Hold-Marker"); got != "hold-A" {
184			t.Fatalf("held marker: got %q, want hold-A", got)
185		}
186	}
187	
188	// assertStillOpen proves the in-flight response has not picked up any further
189	// data (in particular no B content) and has not ended while another
190	// configuration is active.
191	func (h *inflightHold) assertStillOpen(t *testing.T, phase string) {
192		t.Helper()
193		select {
194		case <-h.done:
195			t.Fatalf("held request completed during %s before the upstream was released", phase)
196		case <-time.After(500 * time.Millisecond):
197		}
198	}
199	
200	// waitAndAssertComplete waits for the held response to end (after the upstream
201	// release) and asserts it is exactly the A response in full: A status and
202	// marker already asserted at prefix time, plus a clean read of exactly the A
203	// suffix, with no B payload spliced in, no truncation and no duplicated
204	// prefix.
205	func (h *inflightHold) waitAndAssertComplete(t *testing.T, wantProto int) {
206		t.Helper()
207		select {
208		case <-h.done:
209		case <-time.After(10 * time.Second):
210			t.Fatal("held request never completed after the upstream was released")
211		}
212		if h.restErr != nil {
213			t.Fatalf("reading held response to completion: %v", h.restErr)
214		}
215		if string(h.rest) != holdSuffix {
216			t.Errorf("held suffix: got %q, want %q", h.rest, holdSuffix)
217		}
218		full := string(append(append([]byte{}, h.prefix...), h.rest...))
219		if want := holdPrefix + holdSuffix; full != want {
220			t.Errorf("held full body: got %q, want %q", full, want)
221		}
222		if bytes.Count([]byte(full), []byte(holdPrefix)) != 1 {
223			t.Errorf("held prefix was delivered more than once: %q", full)
224		}
225		if strings.Contains(full, versionBBody) {
226			t.Errorf("held response was spliced with B content: %q", full)
227		}
228		if h.resp.ProtoMajor != wantProto {
229			t.Errorf("held response protocol: got HTTP/%d, want HTTP/%d", h.resp.ProtoMajor, wantProto)
230		}
231	}
