233	// versionResult is the exact /version answer a configuration gave one client.
234	type versionResult struct {
235		status  int
236		variant string
237		body    string
238		proto   int
239	}
240	
241	// versionExpectation is the exact /version answer one configuration must give.
242	type versionExpectation struct {
243		status  int
244		variant string
245		body    string
246	}
247	
248	var (
249		versionA = versionExpectation{status: http.StatusCreated, variant: "A", body: versionABody}
250		versionB = versionExpectation{status: http.StatusAccepted, variant: "B", body: versionBBody}
251	)
252	
253	func fetchVersion(t *testing.T, client *http.Client, baseURL string) versionResult {
254		t.Helper()
255		resp, err := client.Get(baseURL + "/version")
256		if err != nil {
257			t.Fatalf("GET /version: %v", err)
258		}
259		defer resp.Body.Close()
260		body, err := io.ReadAll(resp.Body)
261		if err != nil {
262			t.Fatalf("reading /version body: %v", err)
263		}
264		return versionResult{
265			status:  resp.StatusCode,
266			variant: resp.Header.Get("X-Variant"),
267			body:    string(body),
268			proto:   resp.ProtoMajor,
269		}
270	}
271	
272	func (v versionResult) assertMatches(t *testing.T, want versionExpectation, wantProto int, where string) {
273		t.Helper()
274		if v.status != want.status {
275			t.Errorf("%s: /version status: got %d, want %d", where, v.status, want.status)
276		}
277		if v.variant != want.variant {
278			t.Errorf("%s: /version X-Variant: got %q, want %q", where, v.variant, want.variant)
279		}
280		if v.body != want.body {
281			t.Errorf("%s: /version body: got %q, want %q", where, v.body, want.body)
282		}
283		if v.proto != wantProto {
284			t.Errorf("%s: /version protocol: got HTTP/%d, want HTTP/%d", where, v.proto, wantProto)
285		}
286	}
287	
288	// assertOnlyVariant issues /version over both the shared keep-alive client and
289	// brand-new connections, so an old listener still accepting new connections
290	// after a switch (which would answer the previous variant) cannot hide, and
291	// neither can a brief window in which the address answers nothing.
292	func assertOnlyVariant(t *testing.T, baseURL string, h2 bool, wantProto int, want versionExpectation, where string) {
293		t.Helper()
294		shared := newFailoverClient(h2)
295		for i := 0; i < 16; i++ {
296			client := shared
297			if i%2 == 0 {
298				client = newFailoverClient(h2) // force a brand-new connection
299			}
300			got := fetchVersion(t, client, baseURL)
301			got.assertMatches(t, want, wantProto, fmt.Sprintf("%s request %d", where, i))
302		}
303	}
304	
305	// switchProbe continuously issues /version requests on its own keep-alive
306	// connections while a configuration switch is in flight. Every answer must be
307	// a well-formed A or B answer (which side of the switch boundary a request
308	// lands on is unspecified); a connection error, a missing listener or any
309	// third answer shape would mean the address was briefly unconfigured.
310	type switchProbe struct {
311		done           chan struct{}
312		wg             sync.WaitGroup
313		mu             sync.Mutex
314		errs           []string
315		odd            []string
316		aCount, bCount int
317	}
318	
319	func startSwitchProbe(t *testing.T, baseURL string, h2 bool) *switchProbe {
320		t.Helper()
321		p := &switchProbe{done: make(chan struct{})}
322		wantProto := 1
323		if h2 {
324			wantProto = 2
325		}
326		for w := 0; w < 4; w++ {
327			p.wg.Add(1)
328			go func() {
329				defer p.wg.Done()
330				// one client per worker: connections are reused, so probing never
331				// exhausts the ephemeral port range
332				client := newFailoverClient(h2)
333				for {
334					select {
335					case <-p.done:
336						return
337					default:
338					}
339					resp, err := client.Get(baseURL + "/version")
340					if err != nil {
341						p.mu.Lock()
342						p.errs = append(p.errs, err.Error())
343						p.mu.Unlock()
344						continue
345					}
346					body, _ := io.ReadAll(resp.Body)
347					resp.Body.Close()
348					got := versionResult{
349						status:  resp.StatusCode,
350						variant: resp.Header.Get("X-Variant"),
351						body:    string(body),
352						proto:   resp.ProtoMajor,
353					}
354					p.mu.Lock()
355					switch {
356					case got.status == versionA.status && got.variant == "A" && got.body == versionABody && got.proto == wantProto:
357						p.aCount++
358					case got.status == versionB.status && got.variant == "B" && got.body == versionBBody && got.proto == wantProto:
359						p.bCount++
360					default:
361						p.odd = append(p.odd, fmt.Sprintf("%d %q %q HTTP/%d", got.status, got.variant, got.body, got.proto))
362					}
363					p.mu.Unlock()
364				}
365			}()
366		}
367		return p
368	}
369	
370	func (p *switchProbe) stop() { close(p.done); p.wg.Wait() }
371	
372	// assertCleanAcrossSwitch checks that probing saw neither errors nor malformed
373	// answers, and that it observed both sides of the boundary (A before the switch
374	// completed, B afterwards).
375	func (p *switchProbe) assertCleanAcrossSwitch(t *testing.T, where string) {
376		t.Helper()
377		p.mu.Lock()
378		defer p.mu.Unlock()
379		for _, e := range p.errs {
380			t.Errorf("%s: request failed while the switch was in flight: %s", where, e)
381		}
382		for _, o := range p.odd {
383			t.Errorf("%s: neither A nor B answer while the switch was in flight: %s", where, o)
384		}
385		if p.aCount == 0 {
386			t.Errorf("%s: probe never observed an A answer before the switch completed", where)
387		}
388		if p.bCount == 0 {
389			t.Errorf("%s: probe never observed a B answer after the switch completed", where)
390		}
391	}
