393	// postLoad submits a complete configuration to POST /load.
394	func postLoad(t *testing.T, adminURL, contentType string, body io.Reader) (int, string) {
395		t.Helper()
396		client := &http.Client{Timeout: 30 * time.Second}
397		resp, err := client.Post(adminURL+"/load", contentType, body)
398		if err != nil {
399			t.Fatalf("POST /load: %v", err)
400		}
401		defer resp.Body.Close()
402		respBody, _ := io.ReadAll(resp.Body)
403		return resp.StatusCode, string(respBody)
404	}
405	
406	// assertLoadSucceeds submits a configuration and requires the admin API to
407	// accept it. By the time the 200 is returned the new configuration must be the
408	// one answering new requests.
409	func assertLoadSucceeds(t *testing.T, adminURL, contentType, body, label string) {
410		t.Helper()
411		status, respBody := postLoad(t, adminURL, contentType, strings.NewReader(body))
412		if status != http.StatusOK {
413			t.Fatalf("%s: POST /load status: got %d, want 200; body: %s", label, status, respBody)
414		}
415		if respBody != "" {
416			t.Errorf("%s: POST /load body: got %q, want empty", label, respBody)
417		}
418	}
419	
420	// assertLoadRejected submits an invalid configuration and requires it to be
421	// refused with the duplicate-listener validation error; nothing about the
422	// running configuration may change.
423	func assertLoadRejected(t *testing.T, adminURL, badBody, label string) {
424		t.Helper()
425		status, respBody := postLoad(t, adminURL, "application/json", strings.NewReader(badBody))
426		if status != http.StatusBadRequest {
427			t.Fatalf("%s: POST /load status: got %d, want 400; body: %s", label, status, respBody)
428		}
429		if !strings.Contains(respBody, "listener address repeated") {
430			t.Fatalf("%s: POST /load error: got %q, want it to mention a repeated listener address", label, respBody)
431		}
432	}
