434	// startReloadCaddy launches `caddy run` with the given initial configuration
435	// and waits until /version answers wantReadyStatus, proving the instance owns
436	// the listen address.
437	func startReloadCaddy(t *testing.T, bin, cfgPath, adapter, runDir, adminURL, baseURL string, h2 bool, wantReadyStatus int) *caddyInstance {
438		t.Helper()
439	
440		logFile, err := os.Create(filepath.Join(runDir, "caddy.log"))
441		if err != nil {
442			t.Fatalf("creating log file: %v", err)
443		}
444		args := []string{"run", "--config", cfgPath}
445		if adapter != "" {
446			args = append(args, "--adapter", adapter)
447		}
448		cmd := exec.Command(bin, args...)
449		cmd.Stdout = logFile
450		cmd.Stderr = logFile
451		// isolate every on-disk artifact (autosave, internal CA, locks) from the
452		// developer machine and from other test runs
453		cmd.Env = isolatedCaddyEnv(runDir, "state")
454		if err := cmd.Start(); err != nil {
455			logFile.Close()
456			t.Fatalf("starting caddy: %v", err)
457		}
458	
459		inst := &caddyInstance{
460			cmd:      cmd,
461			logPath:  logFile.Name(),
462			waitDone: make(chan error, 1),
463			adminURL: adminURL,
464		}
465		go func() { inst.waitDone <- cmd.Wait(); logFile.Close() }()
466	
467		client := newFailoverClient(h2)
468		deadline := time.Now().Add(60 * time.Second)
469		for time.Now().Before(deadline) {
470			select {
471			case err := <-inst.waitDone:
472				t.Fatalf("caddy exited before becoming ready: %v\n%s", err, inst.tailLog())
473			default:
474			}
475			resp, err := client.Get(baseURL + "/version")
476			if err == nil {
477				_, _ = io.Copy(io.Discard, resp.Body)
478				resp.Body.Close()
479				if resp.StatusCode == wantReadyStatus {
480					return inst
481				}
482			}
483			time.Sleep(50 * time.Millisecond)
484		}
485		t.Fatalf("caddy did not become ready within 60s\n%s", inst.tailLog())
486		return nil
487	}
