592	}
593	
594	func reloadCaddyfileB(adminAddr, siteAddr string) string {
595		return fmt.Sprintf(`{
596		skip_install_trust
597		admin %s
598		grace_period 60s
599	}
600	%s {
601		tls internal
602		handle /version {
603			header X-Variant B
604			respond %q 202
605		}
606	}
607	`, adminAddr, siteAddr, versionBBody)
608	}
609	
610	// reloadCase parameterizes one protocol matrix.
611	type reloadCase struct {
612		name        string
613		h2          bool
614		wantProto   int
615		siteAddr    string
616		adminAddr   string
617		contentType string // Content-Type used when submitting A and B to /load
618	}
619	
620	// TestConfigReloadInFlightIsolation drives the complete online-switch matrix
621	// on a real caddy binary for a plaintext HTTP/1.1 listener and an HTTPS
622	// HTTP/2 listener:
623	//
624	//  1. A is started and serves A on /version.
625	//  2. a /hold request is opened; once its A prefix has arrived, B is loaded;
626	//  3. from the moment /load answers 200, only B answers new /version requests
627	//     while the held A response stays exactly where it was; concurrent probes
628	//     during the commit prove the address is continuously available;
629	//  4. releasing the upstream completes the held response as exactly A;
630	//  5. an invalid duplicate-listener config is rejected and B keeps serving;
631	//  6. A loads again and a second /hold is opened, interleaving the three
632	//     events: a rolled-back failure (A keeps serving, hold unchanged), then a
633	//     successful commit while the same hold is open (B serves new requests,
634	//     address continuously available), and only then is the request released
635	//     to finish as exactly A;
636	//  7. one more successful load closes the success/failure/success sequence.
637	func TestConfigReloadInFlightIsolation(t *testing.T) {
638		bin := buildCaddyBinary(t)
639	
640		for _, tc := range []reloadCase{
641			{
642				name:        "HTTP/1.1 plaintext",
643				h2:          false,
644				wantProto:   1,
645				siteAddr:    "127.0.0.1:9088",
646				adminAddr:   "127.0.0.1:2992",
647				contentType: "application/json",
648			},
649			{
650				name:        "HTTP/2 over TLS internal",
651				h2:          true,
652				wantProto:   2,
653				siteAddr:    "localhost:9451",
654				adminAddr:   "127.0.0.1:2991",
655				contentType: "text/caddyfile",
656			},
657		} {
658			t.Run(tc.name, func(t *testing.T) {
659				runReloadMatrix(t, bin, tc)
660			})
661		}
662	}
663	
664	func runReloadMatrix(t *testing.T, bin string, tc reloadCase) {
665		upstream := newReloadHoldUpstream(t)
666	
667		adminURL := "http://" + tc.adminAddr
668		scheme := "http"
669		if tc.h2 {
670			scheme = "https"
671		}
672		baseURL := scheme + "://" + tc.siteAddr
673	
674		var cfgA, cfgB, initialCfg, initialName, adapter string
675		if tc.h2 {
676			initialName = "initial.Caddyfile"
677			adapter = "caddyfile"
678			cfgA = reloadCaddyfileA(tc.adminAddr, tc.siteAddr, upstream.addr())
679			cfgB = reloadCaddyfileB(tc.adminAddr, tc.siteAddr)
680		} else {
681			initialName = "initial.json"
682			cfgA = reloadJSONA(tc.adminAddr, tc.siteAddr, upstream.addr())
683			cfgB = reloadJSONB(tc.adminAddr, tc.siteAddr)
684		}
685		initialCfg = cfgA
686		cfgBad := reloadJSONBad(tc.adminAddr, tc.siteAddr)
687	
688		runDir := t.TempDir()
689		cfgPath := filepath.Join(runDir, initialName)
690		if err := os.WriteFile(cfgPath, []byte(initialCfg), 0o600); err != nil {
691			t.Fatalf("writing initial config: %v", err)
692		}
693	
694		inst := startReloadCaddy(t, bin, cfgPath, adapter, runDir, adminURL, baseURL, tc.h2, versionA.status)
695		t.Cleanup(func() { inst.stopCaddy(t) })
696	
697		// the held stream must outlive ordinary request deadlines, the rest of
698		// the matrix uses the standard bounded client
699		holdClient := newFailoverClient(tc.h2)
700		holdClient.Timeout = 0
701		client := newFailoverClient(tc.h2)
702	
703		// 1. A is the running configuration.
704		fetchVersion(t, client, baseURL).assertMatches(t, versionA, tc.wantProto, "initial A")
705	
706		// 2. open /hold and wait for the A prefix before switching anything.
707		held := startInflightHold(t, holdClient, baseURL)
708		held.waitPrefix(t)
709		if got := upstream.variantHit("A"); got != 1 {
710			t.Fatalf("upstream X-Variant=A hits: got %d, want 1", got)
711		}
712		if got := upstream.variantHit("B"); got != 0 {
713			t.Fatalf("upstream unexpectedly received X-Variant=B %d times", got)
714		}
715	
716		// everything immediately before the switch is still A
717		fetchVersion(t, client, baseURL).assertMatches(t, versionA, tc.wantProto, "pre-switch")
718	
719		// 3. load B while the address is being hammered; once this returns, new
720		// requests only ever see B and the address never stopped answering.
721		probe := startSwitchProbe(t, baseURL, tc.h2)
722		// let the probe demonstrably observe A before submitting B
723		time.Sleep(100 * time.Millisecond)
724		assertLoadSucceeds(t, adminURL, tc.contentType, cfgB, "load B")
725		// the successful response already marks the boundary; let probes observe
726		// the B side as well before stopping them
727		time.Sleep(100 * time.Millisecond)
728		probe.stop()
729		probe.assertCleanAcrossSwitch(t, "load B")
730		assertOnlyVariant(t, baseURL, tc.h2, tc.wantProto, versionB, "after B load")
731	
732		// the held response must still be exactly the open A response: no
733		// completion and no extra (B) bytes while B serves new requests
734		held.assertStillOpen(t, "B active")
735	
736		// 4. releasing the upstream finalizes the old response as exactly A.
737		upstream.releaseAll()
738		held.waitAndAssertComplete(t, tc.wantProto)
739		if got := upstream.variantHit("A"); got != 1 {
740			t.Errorf("upstream X-Variant=A hits after release: got %d, want still 1", got)
741		}
742	
743		// 5. a rejected load must not change anything: B keeps serving.
744		assertLoadRejected(t, adminURL, cfgBad, "bad config while B active")
745		assertOnlyVariant(t, baseURL, tc.h2, tc.wantProto, versionB, "after rejected load on B")
746	
747		// 6. A loads successfully again; then a second /hold request is opened and
748		// kept open while the other two events interleave around it: first a
749		// rejected (rolled back) load, then a successful commit. This fixes the
750		// ordering of commit completion, rollback and request release.
751		assertLoadSucceeds(t, adminURL, tc.contentType, cfgA, "reload A")
752		assertOnlyVariant(t, baseURL, tc.h2, tc.wantProto, versionA, "after A reload")
753	
754		held2 := startInflightHold(t, holdClient, baseURL)
755		held2.waitPrefix(t)
756		if got := upstream.variantHit("A"); got != 2 {
757			t.Fatalf("upstream X-Variant=A hits after second hold: got %d, want 2", got)
758		}
759	
760		// 6b. rollback while the request is held: rejected, A keeps serving, and
761		// the held response neither completes nor changes.
762		assertLoadRejected(t, adminURL, cfgBad, "bad config while A active")
763		assertOnlyVariant(t, baseURL, tc.h2, tc.wantProto, versionA, "after rejected load on A")
764		held2.assertStillOpen(t, "rollback while held")
765	
766		// 6c. successful commit while the very same request is held: from the
767		// successful response onwards only B answers new requests, and the address
768		// is continuously available across the boundary.
769		probe2 := startSwitchProbe(t, baseURL, tc.h2)
770		time.Sleep(100 * time.Millisecond)
771		assertLoadSucceeds(t, adminURL, tc.contentType, cfgB, "reload B while held")
772		time.Sleep(100 * time.Millisecond)
773		probe2.stop()
774		probe2.assertCleanAcrossSwitch(t, "reload B while held")
775		assertOnlyVariant(t, baseURL, tc.h2, tc.wantProto, versionB, "after commit while held")
776		held2.assertStillOpen(t, "successful commit while held")
777	
778		// 6d. only now is the request released; it was accepted by A, survived
779		// both a rolled-back failure and a successful commit, and must finish as
780		// exactly A with no B content, truncation or duplication.
781		upstream.releaseAll()
782		held2.waitAndAssertComplete(t, tc.wantProto)
783		if got := upstream.variantHit("A"); got != 2 {
784			t.Errorf("upstream X-Variant=A hits after second release: got %d, want still 2", got)
785		}
786	
787		// 7. one last successful load (A again) completes the
788		// success/failure/success/failure/success chain; every round must stay
789		// isolated from the others.
790		assertLoadSucceeds(t, adminURL, tc.contentType, cfgA, "final reload A")
791		assertOnlyVariant(t, baseURL, tc.h2, tc.wantProto, versionA, "after final A load")
792	}
793

