// config builders for the HTTPS HTTP/2 matrix (Caddyfile with `tls internal`
// submitted to /load).

func reloadCaddyfileA(adminAddr, siteAddr, upstreamAddr string) string {
	return fmt.Sprintf(`{
	skip_install_trust
	admin %s
	grace_period 60s
}
%s {
	tls internal
	handle /version {
		header X-Variant A
		respond %q 201
	}
	handle /hold {
		reverse_proxy %s {
			header_up X-Variant A
		}
	}
